sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* =========================================================
   UNIFIED HR DASHBOARD
   ========================================================= */

.hr-app {
    display: flex;
    min-height: 100vh;
    background: #f7f8fc;
    color: #172554;
    font-family: Arial, Helvetica, sans-serif;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.hr-sidebar {
    width: 280px;
    min-width: 280px;
    background: #ffffff;
    border-right: 1px solid #e5e7eb;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}


/* BRAND */

.brand {
    padding: 22px 24px;
    display: flex;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid #f1f5f9;
}

.brand-icon {
    font-size: 35px;
}

.brand-text {
    display: flex;
    flex-direction: column;
}

.brand-text strong {
    font-size: 18px;
    color: #111827;
}

.brand-text span {
    font-size: 12px;
    color: #64748b;
    margin-top: 2px;
}

.brand-text small {
    font-size: 10px;
    color: #94a3b8;
    margin-top: 3px;
}


/* MENU */

.sidebar-menu {
    padding: 18px 14px;
    flex: 1;
}

.sidebar-link {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 46px;
    padding: 0 14px;
    margin-bottom: 5px;
    border-radius: 8px;
    color: #334155;
    text-decoration: none !important;
    font-size: 14px;
    font-weight: 500;
    transition: all .2s ease;
}

.sidebar-link:hover {
    background: #f1f5ff;
    color: #4338ca;
    text-decoration: none !important;
    transform: translateX(2px);
}

.sidebar-link.active {
    background: #312e81;
    color: white;
}

.sidebar-icon {
    width: 24px;
    text-align: center;
    font-size: 17px;
}

.menu-arrow {
    margin-left: auto;
    font-size: 20px;
    opacity: .6;
}

.notification-badge {
    margin-left: auto;
    min-width: 22px;
    height: 22px;
    padding: 0 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #ef4444;
    color: white;
    border-radius: 20px;
    font-size: 11px;
    font-weight: bold;
}


/* HELP */

.help-box {
    margin: 15px;
    padding: 20px 14px;
    background: #fafaff;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    text-align: center;
}

.help-icon {
    font-size: 30px;
}

.help-box h3 {
    margin: 10px 0 5px;
    font-size: 15px;
}

.help-box p {
    margin: 0 0 14px;
    font-size: 12px;
    color: #64748b;
}

.help-button {
    display: block;
    background: #4338ca;
    color: white !important;
    text-decoration: none !important;
    padding: 10px;
    border-radius: 7px;
    font-size: 12px;
    font-weight: 600;
}

.help-button:hover {
    background: #3730a3;
}


/* SIDEBAR FOOTER */

.sidebar-footer {
    padding: 15px;
    text-align: center;
    color: #94a3b8;
    font-size: 11px;
}


/* =========================================================
   MAIN
   ========================================================= */

.hr-main {
    flex: 1;
    min-width: 0;
    padding: 28px;
}


/* HEADER */

.top-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 25px;
    margin-bottom: 28px;
}

.welcome h1 {
    margin: 0;
    font-size: 27px;
    font-weight: 700;
    color: #172554;
}

.welcome p {
    margin: 8px 0 0;
    color: #64748b;
    font-size: 14px;
}


/* HEADER RIGHT */

.header-right {
    display: flex;
    align-items: center;
    gap: 15px;
}

.search-box {
    width: 390px;
    height: 45px;
    padding: 0 15px;
    display: flex;
    align-items: center;
    gap: 10px;
    background: white;
    border: 1px solid #e2e8f0;
    border-radius: 9px;
    color: #64748b !important;
    text-decoration: none !important;
    font-size: 12px;
}

.search-box:hover {
    border-color: #6366f1;
}

.search-text {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.header-icon {
    position: relative;
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #475569 !important;
    text-decoration: none !important;
    border-radius: 8px;
}

.header-icon:hover {
    background: #f1f5f9;
}

.header-icon span {
    position: absolute;
    top: -2px;
    right: -2px;
    background: #ef4444;
    color: white;
    border-radius: 20px;
    min-width: 17px;
    height: 17px;
    text-align: center;
    font-size: 9px;
    padding-top: 3px;
}

.profile {
    display: flex;
    align-items: center;
    gap: 9px;
    color: #1e293b !important;
    text-decoration: none !important;
}

.profile-avatar {
    width: 38px;
    height: 38px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e0e7ff;
    color: #3730a3;
    border-radius: 50%;
    font-weight: 700;
}

.profile strong,
.profile small {
    display: block;
}

.profile strong {
    font-size: 12px;
}

.profile small {
    color: #64748b;
    font-size: 10px;
    margin-top: 2px;
}


/* =========================================================
   KPI
   ========================================================= */

.kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 20px;
}

.kpi-card {
    position: relative;
    min-height: 125px;
    padding: 20px;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    color: #172554 !important;
    text-decoration: none !important;
    transition: all .2s ease;
}

.kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 22px rgba(15,23,42,.09);
    border-color: #c7d2fe;
}

.kpi-icon {
    width: 45px;
    height: 45px;
    min-width: 45px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    font-size: 21px;
    background: #eef2ff;
}

.leave-card .kpi-icon {
    background: #ecfdf5;
}

.cases-card .kpi-icon {
    background: #fff7ed;
}

.requests-card .kpi-icon {
    background: #eff6ff;
}

.resolution-card .kpi-icon {
    background: #f5f3ff;
}

.kpi-info span,
.kpi-info strong,
.kpi-info small {
    display: block;
}

.kpi-info span {
    font-size: 12px;
    color: #64748b;
    margin-bottom: 7px;
}

.kpi-info strong {
    font-size: 28px;
    color: #172554;
    line-height: 1;
}

.kpi-info small {
    margin-top: 8px;
    font-size: 10px;
    color: #64748b;
}

.kpi-arrow {
    position: absolute;
    right: 16px;
    bottom: 12px;
    color: #4338ca;
    font-size: 18px;
}


/* =========================================================
   GRIDS
   ========================================================= */

.chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 18px;
}

.bottom-grid {
    display: grid;
    grid-template-columns: 1.5fr 1fr 1fr;
    gap: 18px;
}


/* CARD */

.dashboard-card {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    padding: 20px;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 20px;
}

.card-header h2 {
    margin: 0;
    color: #172554;
    font-size: 16px;
}

.card-header p {
    margin: 5px 0 0;
    font-size: 11px;
    color: #94a3b8;
}

.view-link {
    color: #4338ca !important;
    text-decoration: none !important;
    font-size: 11px;
    font-weight: 600;
}

.view-link:hover {
    text-decoration: underline !important;
}


/* =========================================================
   DONUT CHARTS
   ========================================================= */

.leave-chart,
.category-chart {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 45px;
    min-height: 185px;
}

.donut,
.case-donut {
    width: 145px;
    height: 145px;
    min-width: 145px;
    border-radius: 50%;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}

.donut {
    background: conic-gradient(
        #22c55e 0deg 190deg,
        #f59e0b 190deg 285deg,
        #ef4444 285deg 330deg,
        #6366f1 330deg 360deg
    );
}

.case-donut {
    background: conic-gradient(
        #10b981 0deg 90deg,
        #f59e0b 90deg 160deg,
        #8b5cf6 160deg 225deg,
        #ec4899 225deg 290deg,
        #6366f1 290deg 360deg
    );
}

.donut:before,
.case-donut:before {
    content: "";
    position: absolute;
    width: 90px;
    height: 90px;
    background: white;
    border-radius: 50%;
}

.donut-center {
    position: relative;
    z-index: 1;
    text-align: center;
}

.donut-center strong,
.donut-center span {
    display: block;
}

.donut-center strong {
    font-size: 23px;
    color: #172554;
}

.donut-center span {
    font-size: 10px;
    color: #64748b;
}


/* LEGEND */

.legend {
    min-width: 180px;
}

.legend-item {
    display: grid;
    grid-template-columns: 10px 1fr auto;
    align-items: center;
    gap: 8px;
    padding: 7px 4px;
    color: #475569 !important;
    text-decoration: none !important;
    font-size: 11px;
    border-radius: 5px;
}

.legend-item:hover {
    background: #f8fafc;
}

.legend-item strong {
    color: #172554;
}

.legend-dot {
    width: 9px;
    height: 9px;
    border-radius: 50%;
}

.approved {
    background: #22c55e;
}

.pending {
    background: #f59e0b;
}

.rejected {
    background: #ef4444;
}

.cancelled {
    background: #6366f1;
}

.payroll {
    background: #10b981;
}

.leave {
    background: #f59e0b;
}

.onboarding {
    background: #8b5cf6;
}

.policy {
    background: #ec4899;
}

.others {
    background: #6366f1;
}


/* =========================================================
   TABLE
   ========================================================= */

.table-wrapper {
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th {
    padding: 11px 8px;
    text-align: left;
    background: #f8fafc;
    color: #64748b;
    font-size: 10px;
    font-weight: 600;
}

td {
    padding: 12px 8px;
    border-bottom: 1px solid #f1f5f9;
    color: #475569;
    font-size: 11px;
}

.case-link,
.subject-link {
    color: #4338ca !important;
    text-decoration: none !important;
    font-weight: 600;
}

.case-link:hover,
.subject-link:hover {
    text-decoration: underline !important;
}

.status-badge,
.priority-badge {
    display: inline-block;
    padding: 5px 9px;
    border-radius: 6px;
    font-size: 9px;
    text-decoration: none !important;
}

.status-badge {
    background: #e0e7ff;
    color: #3730a3 !important;
}

.priority-badge {
    background: #fef3c7;
    color: #92400e;
}

.priority-badge.priority-low {
    background: #dcfce7;
    color: #166534;
}

.empty {
    text-align: center;
    padding: 25px;
    color: #94a3b8;
}


/* =========================================================
   HOLIDAYS
   ========================================================= */

.holiday-list {
    display: flex;
    flex-direction: column;
}

.holiday-item {
    display: flex;
    gap: 13px;
    padding: 13px 0;
    border-bottom: 1px solid #f1f5f9;
    color: #334155 !important;
    text-decoration: none !important;
}

.holiday-item:hover {
    background: #f8fafc;
}

.holiday-date {
    width: 45px;
    min-width: 45px;
    height: 45px;
    background: #f1f5ff;
    border-radius: 7px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

.holiday-date strong {
    font-size: 17px;
    color: #3730a3;
}

.holiday-date span {
    font-size: 8px;
    color: #64748b;
}

.holiday-item > div:last-child strong,
.holiday-item > div:last-child span {
    display: block;
}

.holiday-item > div:last-child strong {
    font-size: 12px;
    margin-top: 3px;
}

.holiday-item > div:last-child span {
    font-size: 10px;
    color: #94a3b8;
    margin-top: 5px;
}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.quick-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
}

.quick-action {
    min-height: 80px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 7px;
    border: 1px solid #e5e7eb;
    border-radius: 9px;
    background: white;
    color: #334155 !important;
    text-decoration: none !important;
    transition: .2s;
}

.quick-action span {
    font-size: 22px;
}

.quick-action strong {
    font-size: 10px;
}

.quick-action:hover {
    background: #f5f3ff;
    border-color: #6366f1;
    color: #3730a3 !important;
    transform: translateY(-2px);
}


/* =========================================================
   FOOTER
   ========================================================= */

.dashboard-footer {
    display: flex;
    justify-content: space-between;
    padding: 25px 5px 5px;
    color: #94a3b8;
    font-size: 10px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1300px) {

    .kpi-grid {
        grid-template-columns: repeat(3, 1fr);
    }

    .bottom-grid {
        grid-template-columns: 1fr 1fr;
    }

    .recent-card {
        grid-column: span 2;
    }

    .search-box {
        width: 280px;
    }

}


@media (max-width: 900px) {

    .hr-sidebar {
        width: 75px;
        min-width: 75px;
    }

    .brand-text,
    .sidebar-link span:not(.sidebar-icon),
    .menu-arrow,
    .notification-badge,
    .help-box,
    .sidebar-footer {
        display: none;
    }

    .sidebar-link {
        justify-content: center;
        padding: 0;
    }

    .hr-main {
        padding: 18px;
    }

    .top-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .header-right {
        width: 100%;
    }

    .search-box {
        flex: 1;
        width: auto;
    }

    .chart-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 650px) {

    .kpi-grid {
        grid-template-columns: 1fr;
    }

    .bottom-grid {
        grid-template-columns: 1fr;
    }

    .recent-card {
        grid-column: span 1;
    }

    .leave-chart,
    .category-chart {
        flex-direction: column;
        gap: 20px;
    }

    .dashboard-footer {
        flex-direction: column;
        gap: 8px;
    }

}

sp_widget.script:
(function() {

    /* =========================================================
       UNIFIED HR DASHBOARD - SERVER SCRIPT
       Dynamic data with safe fallbacks
       ========================================================= */

    data = data || {};

    /* ---------------------------------------------------------
       Helper: safely count records
       --------------------------------------------------------- */
    function getCount(tableName, encodedQuery) {

        try {

            var gr = new GlideRecord(tableName);

            if (!gr.isValid()) {
                return 0;
            }

            if (encodedQuery) {
                gr.addEncodedQuery(encodedQuery);
            }

            gr.query();

            return gr.getRowCount();

        } catch (e) {

            gs.error("HR Dashboard count error - " + tableName +
                     ": " + e.message);

            return 0;
        }
    }


    /* ---------------------------------------------------------
       EMPLOYEES
       --------------------------------------------------------- */

    data.totalEmployees = getCount("sys_user", "active=true");


    /* ---------------------------------------------------------
       LEAVE REQUESTS

       Change table/query here later if your custom leave table
       has a different name.
       --------------------------------------------------------- */

    data.leaveRequests = 0;
    data.leavePending = 0;
    data.leaveApproved = 0;
    data.leaveRejected = 0;
    data.leaveCancelled = 0;

    try {

        var leaveTable = "sysapproval_approver";
        var leaveGR = new GlideRecord(leaveTable);

        if (leaveGR.isValid()) {

            leaveGR.addQuery("state", "requested");
            leaveGR.query();

            data.leavePending = leaveGR.getRowCount();
        }

    } catch (e1) {

        data.leavePending = 0;
    }


    /* ---------------------------------------------------------
       HR CASES
       --------------------------------------------------------- */

    data.openCases = 0;
    data.newCases = 0;
    data.inProgressCases = 0;
    data.onHoldCases = 0;
    data.resolvedCases = 0;

    try {

        var hrCase = new GlideRecord("sn_hr_core_case");

        if (hrCase.isValid()) {

            /* Open cases */
            hrCase.addQuery("active", true);
            hrCase.query();

            data.openCases = hrCase.getRowCount();


            /* New */
            hrCase = new GlideRecord("sn_hr_core_case");
            hrCase.addQuery("state", "1");
            hrCase.query();

            data.newCases = hrCase.getRowCount();


            /* In Progress */
            hrCase = new GlideRecord("sn_hr_core_case");
            hrCase.addQuery("state", "2");
            hrCase.query();

            data.inProgressCases = hrCase.getRowCount();


            /* On Hold */
            hrCase = new GlideRecord("sn_hr_core_case");
            hrCase.addQuery("state", "3");
            hrCase.query();

            data.onHoldCases = hrCase.getRowCount();


            /* Resolved */
            hrCase = new GlideRecord("sn_hr_core_case");
            hrCase.addQuery("state", "6");
            hrCase.query();

            data.resolvedCases = hrCase.getRowCount();
        }

    } catch (e2) {

        data.openCases = 0;
        data.newCases = 0;
        data.inProgressCases = 0;
        data.onHoldCases = 0;
        data.resolvedCases = 0;
    }


    /* ---------------------------------------------------------
       REQUESTS THIS MONTH
       --------------------------------------------------------- */

    data.requestsThisMonth = 0;

    try {

        var requestGR = new GlideRecord("sc_request");

        if (requestGR.isValid()) {

            requestGR.addEncodedQuery(
                "sys_created_onONThis month@javascript:gs.beginningOfThisMonth()@javascript:gs.endOfThisMonth()"
            );

            requestGR.query();

            data.requestsThisMonth = requestGR.getRowCount();
        }

    } catch (e3) {

        data.requestsThisMonth = 0;
    }


    /* ---------------------------------------------------------
       AVERAGE RESOLUTION TIME
       --------------------------------------------------------- */

    data.avgResolutionTime = "2.6";
    data.avgResolutionUnit = "Days";


    /* ---------------------------------------------------------
       LEAVE STATUS CHART
       --------------------------------------------------------- */

    data.leaveChart = {
        approved: data.leaveApproved || 0,
        pending: data.leavePending || 0,
        rejected: data.leaveRejected || 0,
        cancelled: data.leaveCancelled || 0
    };


    /* ---------------------------------------------------------
       HR CASE CATEGORY CHART
       --------------------------------------------------------- */

    data.caseCategories = {
        payroll: 0,
        leave: 0,
        onboarding: 0,
        policies: 0,
        others: 0
    };


    /* ---------------------------------------------------------
       RECENT HR CASES
       --------------------------------------------------------- */

    data.recentCases = [];

    try {

        var recent = new GlideRecord("sn_hr_core_case");

        if (recent.isValid()) {

            recent.orderByDesc("sys_created_on");
            recent.setLimit(5);
            recent.query();

            while (recent.next()) {

                var caseItem = {};

                caseItem.id = recent.getDisplayValue("number") || "";
                caseItem.subject =
                    recent.getDisplayValue("short_description") ||
                    recent.getDisplayValue("description") ||
                    "HR Case";

                caseItem.requestedBy =
                    recent.getDisplayValue("opened_for") || "";

                caseItem.status =
                    recent.getDisplayValue("state") || "New";

                caseItem.priority =
                    recent.getDisplayValue("priority") || "Medium";

                data.recentCases.push(caseItem);
            }
        }

    } catch (e4) {

        data.recentCases = [];
    }


    /* ---------------------------------------------------------
       UPCOMING HOLIDAYS
       --------------------------------------------------------- */

    data.holidays = [];


    /* ---------------------------------------------------------
       DASHBOARD SUMMARY
       --------------------------------------------------------- */

    data.summary = {
        employees: data.totalEmployees || 0,
        leaves: data.leaveRequests || 0,
        cases: data.openCases || 0,
        requests: data.requestsThisMonth || 0,
        resolutionTime: data.avgResolutionTime || "0"
    };


    /* ---------------------------------------------------------
       IMPORTANT:
       Never allow dashboard objects to become null.
       --------------------------------------------------------- */

    if (!data.recentCases) {
        data.recentCases = [];
    }

    if (!data.holidays) {
        data.holidays = [];
    }

    if (!data.leaveChart) {
        data.leaveChart = {
            approved: 0,
            pending: 0,
            rejected: 0,
            cancelled: 0
        };
    }

    if (!data.caseCategories) {
        data.caseCategories = {
            payroll: 0,
            leave: 0,
            onboarding: 0,
            policies: 0,
            others: 0
        };
    }

})();
